import { useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { ClipboardCheck, Eye, EyeOff, AlertCircle, Languages, X, CheckCircle2, Moon, Sun } from "lucide-react";
import { apiPost, setToken, setUser } from "../lib/api.js";
import { useLang } from "../lib/i18n.jsx";
import { useTheme } from "../lib/theme.jsx";
import { usePasskeySignIn, biometricLabel } from "../components/PasskeySignIn.jsx";

// One-time cleanup of plaintext passwords two earlier builds left under these
// keys. Unrelated to the current REMEMBER_KEY below; must run before it writes.
try {
  localStorage.removeItem("mg_remember");
  localStorage.removeItem("mg_remember_v2");
} catch { /* ignore */ }

// "Remember password" stores { staffId, password } as plain JSON in
// localStorage — a DELIBERATE, requested trade-off, not an oversight. Chrome's
// native "Save password?" prompt never reliably fires for this SPA
// (credentials.store() resolves but nothing persists), so the browser-native
// path is a dead end. Cost: the password is readable by anyone with the browser
// profile, not OS-keychain-encrypted.
//
// MUST STAY DEV-GATED. `import.meta.env.DEV` is true only under `vite dev`, so
// a production build has NO code path that reads or writes a plaintext
// password. Do not remove the gate. The checkbox stays visible either way
// because it also drives the harmless "keep me signed in" half (localStorage
// vs sessionStorage, via setToken(token, keep)).
const REMEMBER_ENABLED = import.meta.env.DEV;
const REMEMBER_KEY = "mg_remembered_login";
function loadRemembered() {
  if (!REMEMBER_ENABLED) return null;
  try {
    const raw = localStorage.getItem(REMEMBER_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}
function saveRemembered(staffId, password) {
  if (!REMEMBER_ENABLED) return;
  try { localStorage.setItem(REMEMBER_KEY, JSON.stringify({ staffId, password })); } catch { /* ignore */ }
}
function clearRemembered() {
  if (!REMEMBER_ENABLED) return;
  try { localStorage.removeItem(REMEMBER_KEY); } catch { /* ignore */ }
}

/**
 * Screen 1 — Login / Authentication (shared across team; Vance leads).
 *
 * Validates against POST /api/auth/login using Account-control-managed
 * accounts. "Remember password" (see REMEMBER_KEY above) both keeps the token
 * in localStorage and prefills the fields.
 *
 * Desktop vs. mobile is NOT chosen here — App.jsx's handleSignIn derives it
 * from the account's permissions, falling back to viewport width.
 */
export default function LoginPage({ onSignIn }) {
  const navigate = useNavigate();
  const { lang, toggleLang, t } = useLang();
  const { theme, toggleTheme } = useTheme();
  const remembered = loadRemembered();
  const [staffId, setStaffId] = useState(remembered?.staffId || "");
  const [password, setPassword] = useState(remembered?.password || "");
  const [showPw, setShowPw] = useState(false);
  const [keep, setKeep] = useState(!!remembered); // "Remember password" — see REMEMBER_KEY note above
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [forgotOpen, setForgotOpen] = useState(false);

  // Biometric sign-in (Vimal — components/PasskeySignIn.jsx), merged into the
  // single "Sign in" button: submit() tries passkey.attempt() first when this
  // device has one, then silently falls through to Staff ID + password.
  const passkey = usePasskeySignIn({ staffId, keep, onSignedIn: () => onSignIn?.() });

  // Do NOT re-add auto-attempt-on-mount: it fired the OS biometric prompt with
  // no click, including right after logout (that redirect is a fresh mount).
  // passkey.attempt() must only run from submit().

  async function submit() {
    setError("");
    setSubmitting(true);
    try {
      if (passkey.available && passkey.registered) {
        const signedInViaPasskey = await passkey.attempt();
        if (signedInViaPasskey) return; // onSignedIn already fired
        // else: fall through to the normal password flow below
      }

      if (!staffId.trim() || !password) {
        setError("Please enter your Staff ID and password.");
        return;
      }

      const { token, name, role, readOnly, username, permissions } = await apiPost("/auth/login", {
        staffId: staffId.trim(),
        password,
      });
      if (token) {
        setToken(token, keep); // keep = "Remember password" checkbox — localStorage vs sessionStorage only
        setUser({ staffId: username || staffId.trim(), username: username || staffId.trim(), name, role, readOnly, permissions }, keep);
        // Stores the actual password — see the REMEMBER_KEY note up top.
        if (keep) saveRemembered(staffId.trim(), password);
        else clearRemembered();
      }
      onSignIn?.(); // success -> enter the app
    } catch (e) {
      // Branch on e.status (from lib/api.js's toError), never message text —
      // the backend sends real messages now, not bare codes.
      if (e?.status === 401) {
        setError("Incorrect Staff ID or password.");
      } else if (e?.status === 429) {
        setError("Too many attempts. Please wait a few minutes and try again.");
      } else if (e?.status === 400) {
        setError("Please enter your Staff ID and password.");
      } else if (e?.code === "ACCOUNT_PENDING") {
        setError("Your account is awaiting admin approval.");
      } else if (e?.code === "ACCOUNT_REJECTED") {
        setError("Your registration was not approved. Contact an admin.");
      } else {
        setError("Can't reach the server. Make sure the backend is running.");
      }
    } finally {
      setSubmitting(false);
    }
  }

  function onKeyDown(e) {
    if (e.key === "Enter") submit();
  }

  return (
    <div style={S.wrap}>
      <div className="row" style={{ position: "absolute", top: 20, right: 20, gap: 10 }}>
        <button
          onClick={toggleTheme}
          className="btn btn-ghost"
          aria-label={theme === "dark" ? t("Switch to light mode") : t("Switch to dark mode")}
        >
          {theme === "dark" ? <Sun size={16} /> : <Moon size={16} />}
        </button>
        <button onClick={toggleLang} className="btn btn-ghost">
          <Languages size={16} /> {lang === "en" ? "中文" : "English"}
        </button>
      </div>
      <div className="login-card" style={S.card}>
        {/* Brand panel */}
        <div className="login-panel" style={S.brand}>
          <div className="wordmark" style={{ color: "#fff", fontSize: 30 }}>
            <ClipboardCheck size={30} strokeWidth={2.4} /> MusterGo
          </div>
          <div>
            <h2 style={S.brandH}>{t("No one gets left behind.")}</h2>
            <p style={S.brandP}>{t("Real-time delegation attendance for SCCCI overseas trips.")}</p>
          </div>
          <p style={S.brandFoot}>{t("A Singapore Chinese Chamber of Commerce & Industry initiative")}</p>
        </div>

        {/* A real <form> with name/autoComplete hints, or the browser's own
            "save password?" prompt never fires. preventDefault + submit() keeps
            the token-based "keep me signed in" logic unchanged. */}
        <form
          className="login-panel"
          style={S.form}
          onSubmit={(e) => { e.preventDefault(); submit(); }}
        >
          <h1 style={{ fontSize: 26 }}>{t("Sign in")}</h1>
          <p className="muted" style={{ marginTop: 4, marginBottom: 24, fontSize: 14 }}>
            {t("SCCCI secretariat & on-ground staff")}
          </p>

          <label className="field-label" htmlFor="staffId">{t("Staff ID")}</label>
          <input
            id="staffId"
            name="username"
            autoComplete="username"
            className="input"
            placeholder="e.g. SCCCI132"
            value={staffId}
            disabled={submitting || passkey.busy}
            onChange={(e) => setStaffId(e.target.value)}
          />

          <label className="field-label" htmlFor="pw" style={{ marginTop: 16 }}>{t("Password")}</label>
          <div style={{ position: "relative" }}>
            <input
              id="pw"
              name="password"
              autoComplete="current-password"
              className="input"
              type={showPw ? "text" : "password"}
              placeholder="............"
              value={password}
              disabled={submitting}
              onChange={(e) => setPassword(e.target.value)}
              style={{ paddingRight: 42 }}
            />
            <button
              type="button"
              onClick={() => setShowPw((v) => !v)}
              aria-label={showPw ? "Hide password" : "Show password"}
              style={S.eye}
            >
              {showPw ? <EyeOff size={18} /> : <Eye size={18} />}
            </button>
          </div>

          {/* Inline error */}
          {error && (
            <div style={S.error} role="alert">
              {/* error holds English; t() re-renders it if the user toggles
                  language after the error appears */}
              <AlertCircle size={16} /> {t(error)}
            </div>
          )}

          <div className="row between" style={{ margin: "14px 0 22px" }}>
            <label className="row" style={{ gap: 8, fontSize: 13, cursor: "pointer" }}>
              <input type="checkbox" checked={keep} onChange={(e) => setKeep(e.target.checked)} />
              {t("Remember password")}
            </label>
            <button
              type="button"
              onClick={() => setForgotOpen(true)}
              style={{ background: "none", border: "none", padding: 0, cursor: "pointer", color: "var(--scc-red)", fontSize: 13, fontWeight: 600, textDecoration: "none" }}
            >
              {t("Forgot password?")}
            </button>
          </div>

          <button type="submit" className="btn btn-primary btn-block" disabled={submitting || passkey.busy}>
            {passkey.busy ? t("Waiting for your device…") : submitting ? t("Signing in…") : t("Sign in")}
          </button>

          {/* No separate biometric button — submit() above handles it. */}
          {passkey.available && passkey.registered && (
            <p className="muted" style={{ fontSize: 12, textAlign: "center", marginTop: 10 }}>
              {t("Uses")} {biometricLabel()} {t("on this device if you've set it up.")}
            </p>
          )}

          <p className="muted" style={{ fontSize: 11, textAlign: "center", marginTop: 16 }}>
            {t("By signing in, you accept the SCCCI data handling policy.")}
          </p>

          {/* Self-service registration — new accounts start "pending" and need
              admin approval before sign-in (RegisterPage.jsx). */}
          <p className="muted" style={{ fontSize: 13, textAlign: "center", marginTop: 14 }}>
            {t("New staff?")}{" "}
            <button
              type="button"
              onClick={() => navigate("/register")}
              style={{ background: "none", border: "none", padding: 0, cursor: "pointer", color: "var(--scc-red)", fontSize: 13, fontWeight: 600 }}
            >
              {t("Create an account")}
            </button>
          </p>
        </form>
      </div>

      {forgotOpen && <ForgotPasswordModal onClose={() => setForgotOpen(false)} />}

      <style>{`
        .login-card { display: grid; grid-template-columns: 1fr 1fr; }
        @media (max-width: 720px) {
          .login-card { grid-template-columns: 1fr; }
          .login-panel { padding: 24px !important; }
        }
      `}</style>
    </div>
  );
}

/**
 * Self-service password reset. WARNING: reachable without being signed in and
 * verifies nothing beyond the username existing — no old password, no OTP. So
 * anyone knowing a username can take over that account; accepted only for this
 * project's small trusted-team context. See resetPassword() in backend/data.js.
 */
function ForgotPasswordModal({ onClose }) {
  const { t } = useLang();
  const [username, setUsername] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  // Only dismiss if the gesture STARTED on the backdrop — otherwise a
  // drag-select inside a password field closes the modal.
  const downOnBackdrop = useRef(false);

  async function handleSubmit() {
    setError("");
    if (!username.trim() || !newPassword || !confirmPassword) {
      setError("Please fill in every field.");
      return;
    }
    if (newPassword !== confirmPassword) {
      setError("Passwords don't match.");
      return;
    }
    setSubmitting(true);
    try {
      await apiPost("/auth/reset-password", { username: username.trim(), newPassword });
      setDone(true);
    } catch (e) {
      setError(
        e?.status === 429
          ? "Too many attempts. Please wait a few minutes and try again."
          : e.message || "Couldn't reset that account. Check the username and try again."
      );
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div style={S.overlay}
      onMouseDown={(e) => { downOnBackdrop.current = e.target === e.currentTarget; }}
      onClick={(e) => { if (!submitting && downOnBackdrop.current && e.target === e.currentTarget) onClose(); }}>
      <div className="card" style={S.modal} onClick={(e) => e.stopPropagation()}>
        <div className="row between" style={{ marginBottom: 18 }}>
          <h2 style={{ fontSize: 18 }}>{t("Reset password")}</h2>
          <button onClick={onClose} style={S.iconBtn} aria-label={t("Close")}><X size={18} /></button>
        </div>

        {done ? (
          <div style={{ textAlign: "center", padding: "12px 0" }}>
            <CheckCircle2 size={32} color="var(--st-present)" style={{ marginBottom: 10 }} />
            <p style={{ fontSize: 14, fontWeight: 600 }}>{t("Password reset. You can sign in with it now.")}</p>
            <button className="btn btn-primary btn-block" style={{ marginTop: 18 }} onClick={onClose}>{t("Back to sign in")}</button>
          </div>
        ) : (
          <>
            <label className="field-label">{t("Username")}</label>
            <input className="input mono" autoFocus value={username}
              placeholder="e.g. staff_123"
              onChange={(e) => setUsername(e.target.value)} />

            <label className="field-label" style={{ marginTop: 14 }}>{t("New password")}</label>
            <input className="input" type="password" value={newPassword}
              placeholder="············"
              onChange={(e) => setNewPassword(e.target.value)} />

            <label className="field-label" style={{ marginTop: 14 }}>{t("Confirm new password")}</label>
            <input className="input" type="password" value={confirmPassword}
              placeholder="············"
              onChange={(e) => setConfirmPassword(e.target.value)} />
            <p className="muted" style={{ fontSize: 12, marginTop: 6 }}>{t("At least 8 characters, including a letter and a number.")}</p>

            {error && (
              <div style={S.error}>
                <AlertCircle size={15} /> {t(error)}
              </div>
            )}

            <div className="row" style={{ gap: 10, marginTop: 22, justifyContent: "flex-end" }}>
              <button className="btn btn-ghost" onClick={onClose} disabled={submitting}>{t("Cancel")}</button>
              <button className="btn btn-primary" onClick={handleSubmit} disabled={submitting}>
                {submitting ? t("Saving…") : t("Reset password")}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

const S = {
  wrap: { minHeight: "100vh", display: "grid", placeItems: "center", padding: 24, background: "var(--bg)" },
  card: {
    width: "min(880px, 100%)",
    maxHeight: "calc(100vh - 48px)",
    background: "var(--surface)",
    borderRadius: "var(--r-lg)",
    overflow: "hidden",
    overflowY: "auto",
    boxShadow: "var(--shadow-lg)",
  },
  brand: {
    background: "var(--scc-red)",
    color: "#fff",
    padding: 40,
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    gap: 40,
  },
  brandH: { fontSize: 28, lineHeight: 1.2, fontWeight: 700 },
  brandP: { marginTop: 10, opacity: 0.9, fontSize: 15, lineHeight: 1.5 },
  brandFoot: { fontSize: 12, opacity: 0.8, fontWeight: 600 },
  form: { padding: 40 },
  eye: {
    position: "absolute", right: 10, top: "50%", transform: "translateY(-50%)",
    background: "none", border: "none", color: "var(--scc-red)", display: "flex",
  },
  error: {
    display: "flex", alignItems: "center", gap: 8,
    marginTop: 14, padding: "10px 12px",
    background: "var(--st-missing-bg)", color: "var(--st-missing)",
    borderRadius: "var(--r-sm)", fontSize: 13, fontWeight: 600,
  },
  overlay: { position: "fixed", inset: 0, background: "rgba(16,24,40,0.45)", display: "grid", placeItems: "center", padding: 20, zIndex: 50 },
  modal: { width: "min(420px, 100%)", padding: 24, background: "var(--surface)" },
  iconBtn: { background: "none", border: "none", color: "var(--ink-3)", display: "flex", padding: 4, borderRadius: 6 },
};
